import 'package:flutter/foundation.dart'; import '../models/appointment_slot.dart'; import '../models/booking_result.dart'; import '../repositories/appointment_repository.dart'; class BookingViewModel extends ChangeNotifier { BookingViewModel(this._repository,this.doctorId):selectedDate=DateTime.now(); final AppointmentRepository _repository; final String doctorId; DateTime selectedDate; List<AppointmentSlot> slots=[]; AppointmentSlot? selectedSlot; BookingResult? result; bool isLoading=false; Future<void> loadSlots() async{isLoading=true;notifyListeners();try{slots=await _repository.fetchSlots(doctorId,selectedDate);}finally{isLoading=false;notifyListeners();}} void selectSlot(AppointmentSlot slot){if(!slot.isFull){selectedSlot=slot;notifyListeners();}} Future<void> confirm() async{if(selectedSlot==null)return;result=await _repository.bookSlot(doctorId,selectedDate,selectedSlot!.id);notifyListeners();} }
